// Gelen body verisini al
const body = $input.item.json.body || $input.item.json;

// Helper: Markdown metinleri HTML'e çevirme fonksiyonu
function markdownToHtml(text) {
  if (!text) return "";
  return text
    .replace(/\n/g, "<br>")                          // Satır başlarını <br> yap
    .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>") // **kalın** yazıları <strong> yap
    .replace(/\*(.*?)\*/g, "<em>$1</em>");           // *italik* yazıları <em> yap
}

// Parametreleri temizle ve hazırla
const riskGroup = body.risk_group || "Bilinmeyen Küme";
const isHighRisk = riskGroup.includes("🔴") || body.action_type.includes("None");

const targetCount = body.target_count || 0;
const targetEmail = body.target_email || "hr@company.com";
const rawMediaLink = body.media_link;

// Media link '#' geldiyse varsayılan YouTube/Spotify Arama linki koy
const mediaLink = (!rawMediaLink || rawMediaLink === "#") 
  ? "https://open.spotify.com/genre/wellness-page" 
  : rawMediaLink;

const motivationMessageHtml = markdownToHtml(body.motivation_message);
const ilaveAksiyonHtml = markdownToHtml(body.ilave_aksiyon);

// -------------------------------------------------------------
// 1. İK ERKEN UYARI MAİL ŞABLONU (YÜKSEK RİSK - RED THEME)
// -------------------------------------------------------------
const hrEmailSubject = `🚨 [İK ERKEN UYARI] ${riskGroup} - Aksiyon Planı`;
const hrEmailBodyHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; background-color: #f4f6f9; margin: 0; padding: 20px; color: #333; }
    .container { max-width: 650px; background: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.08); margin: 0 auto; }
    .header-red { background: #dc3545; color: #ffffff; padding: 20px 25px; }
    .header-red h2 { margin: 0; font-size: 20px; }
    .content { padding: 25px; }
    .badge { display: inline-block; background: #ffeef0; color: #dc3545; font-weight: bold; padding: 6px 12px; border-radius: 4px; font-size: 13px; margin-bottom: 15px; }
    .box { background: #f8f9fa; border-left: 4px solid #dc3545; padding: 15px; border-radius: 4px; margin-bottom: 20px; font-size: 14px; line-height: 1.6; }
    .box-green { background: #f0fff4; border-left: 4px solid #28a745; padding: 15px; border-radius: 4px; margin-bottom: 20px; font-size: 14px; line-height: 1.6; }
    .footer { text-align: center; font-size: 12px; color: #888; padding: 15px; border-top: 1px solid #eee; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header-red">
      <h2>🚨 İK Erken Uyarı & Risk Müdahale Raporu</h2>
    </div>
    <div class="content">
      <div class="badge">Etkilenen Kitle: ${targetCount} Çalışan</div>
      <h3>Hedef Risk Grubu:</h3>
      <p><strong>${riskGroup}</strong></p>

      <h3>🎯 Stratejik İK Aksiyon Planı (LLM):</h3>
      <div class="box">
        ${ilaveAksiyonHtml}
      </div>

      <h3>💬 Çalışanlara Gönderilecek / Önerilen İletişim Metni:</h3>
      <div class="box-green">
        ${motivationMessageHtml}
      </div>
    </div>
    <div class="footer">
      Bu e-posta HR Analytics Otomasyon Sistemi tarafından otomatik oluşturulmuştur.
    </div>
  </div>
</body>
</html>
`;

// -------------------------------------------------------------
// 2. ESENLİK BÜLTENİ MAİL ŞABLONU (WELLNESS - GREEN/PURPLE THEME)
// -------------------------------------------------------------
const wellnessEmailSubject = `🌿 Haftalık Cuma Esenlik Bülteniniz & Müzik Molası 🎧`;
const wellnessEmailBodyHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; background-color: #f0f4f8; margin: 0; padding: 20px; color: #2d3748; }
    .container { max-width: 600px; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.05); margin: 0 auto; }
    .header-green { background: linear-gradient(135deg, #1db954 0%, #191414 100%); color: #ffffff; padding: 30px 25px; text-align: center; }
    .header-green h1 { margin: 0; font-size: 22px; font-weight: 600; }
    .content { padding: 30px 25px; font-size: 15px; line-height: 1.7; color: #4a5568; }
    .btn-spotify { display: inline-block; background-color: #1db954; color: #ffffff !important; font-weight: bold; text-decoration: none; padding: 14px 28px; border-radius: 30px; margin: 20px 0; text-align: center; font-size: 15px; }
    .footer { text-align: center; font-size: 12px; color: #a0aec0; padding: 20px; background: #f7fafc; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header-green">
      <h1>🎧 Haftanın Esenlik & Müzik Molası</h1>
    </div>
    <div class="content">
      ${motivationMessageHtml}

      <div style="text-align: center; margin-top: 25px;">
        <a href="${mediaLink}" target="_blank" class="btn-spotify">
          🎵 Önerilen Listeyi Spotify'da Dinle
        </a>
      </div>
    </div>
    <div class="footer">
      Sevgiyle,<br><strong>İnsan Kaynakları & Wellbeing Ekibi</strong>
    </div>
  </div>
</body>
</html>
`;

// Çıktıyı n8n formatında döndür
return {
  json: {
    is_high_risk: isHighRisk,
    target_email: targetEmail,
    risk_group: riskGroup,

    // İK Mail Verileri
    hr_subject: hrEmailSubject,
    hr_html: hrEmailBodyHtml,

    // Esenlik Mail Verileri
    wellness_subject: wellnessEmailSubject,
    wellness_html: wellnessEmailBodyHtml
  }
};
